import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import { fileURLToPath } from 'node:url';

/*
 * Add only source-obligated semantic words to solutionImageCaption.  The
 * question text, solution, answer, choices, and SVG are not regenerated by
 * this tool.  It is intentionally a targeted field patch so the caption
 * remains a student-facing summary rather than becoming a copy of the source.
 */

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const EXAM_ROOT = path.join(ROOT, 'archive', 'exams', 'original', 'high', 'h1');
const UNITS = new Set(['H15-SA-10', 'H22-C2-02']);

function walk(dir) {
  const files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) files.push(...walk(full));
    else if (entry.isFile() && entry.name.endsWith('.js')) files.push(full);
  }
  return files;
}

function loadBank(file, source) {
  const context = { window: {} };
  vm.createContext(context);
  vm.runInContext(source ?? fs.readFileSync(file, 'utf8'), context, { filename: file, timeout: 5000 });
  return context.window.questionBank || [];
}

function ranges(text) {
  const start = text.indexOf('window.questionBank');
  const array = text.indexOf('[', start);
  const result = [];
  let curly = 0;
  let quote = false;
  let escaped = false;
  let begin = -1;
  for (let index = array + 1; index < text.length; index += 1) {
    const character = text[index];
    if (quote) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = false;
      continue;
    }
    if (character === '"') quote = true;
    else if (character === '{') {
      if (curly === 0) begin = index;
      curly += 1;
    } else if (character === '}') {
      curly -= 1;
      if (curly === 0) result.push([begin, index + 1]);
    } else if (character === ']' && curly === 0) break;
  }
  return result;
}

function semanticTerms(q) {
  const text = `${q.content || ''}\n${q.solution || ''}`;
  const terms = [];
  if (/평행/.test(text)) terms.push('평행 관계');
  if (/서로\s*수직|수직인|수직이고|수직일(?:\s*때)?|직각/.test(text)) terms.push('수직 관계');
  if (/교점|교차|만나는|공통점/.test(text)) terms.push('교점');
  if (/절편|x축|y축/.test(text)) terms.push('절편');
  if (/거리/.test(text)) terms.push('거리');
  return terms;
}

function addCaption(source, q) {
  const prefix = semanticTerms(q).filter((term) => !String(q.solutionImageCaption || '').includes(term));
  if (!prefix.length) return String(q.solutionImageCaption || '');
  const current = String(q.solutionImageCaption || '').trim();
  return [...prefix, current].filter(Boolean).join(' · ');
}

const changed = [];
for (const file of walk(EXAM_ROOT)) {
  let source = fs.readFileSync(file, 'utf8');
  const original = source;
  const objects = ranges(source).map(([start, end]) => ({ start, end, q: vm.runInNewContext(`(${source.slice(start, end)})`, {}, { timeout: 1000 }) }));
  const replacements = [];
  for (const object of objects) {
    if (!UNITS.has(object.q.standardUnitKey) || !object.q.solutionImage) continue;
    const caption = addCaption(source, object.q);
    if (caption === object.q.solutionImageCaption) continue;
    const objectText = source.slice(object.start, object.end);
    const match = objectText.match(/("solutionImageCaption"\s*:\s*)"((?:\\.|[^"\\])*)"/);
    if (!match) throw new Error(`solutionImageCaption field missing for ${path.basename(file)}#${object.q.id}`);
    replacements.push({
      start: object.start + match.index + match[1].length,
      end: object.start + match.index + match[0].length,
      value: JSON.stringify(caption),
      key: `${path.basename(file)}#${object.q.id}`,
    });
  }
  for (const replacement of replacements.sort((left, right) => right.start - left.start)) source = `${source.slice(0, replacement.start)}${replacement.value}${source.slice(replacement.end)}`;
  if (source !== original) {
    fs.writeFileSync(file, source, 'utf8');
    changed.push({ file: path.relative(ROOT, file).replaceAll(path.sep, '/'), count: replacements.length, keys: replacements.map((item) => item.key) });
  }
}

console.log(JSON.stringify({ status: 'PASS', changedFiles: changed.length, changedQuestions: changed.reduce((sum, item) => sum + item.count, 0), changed }, null, 2));
